package com.lmspilot.configuration.platform;import java.util.regex.Pattern;public record BrandingSpec(String systemName,String introduction,String primaryColor,String secondaryColor,String backgroundColor,String textColor){private static final Pattern HEX=Pattern.compile("^#[0-9A-Fa-f]{6}([0-9A-Fa-f]{2})?$");public BrandingSpec{if(systemName==null||systemName.isBlank()||systemName.length()>240)throw new IllegalArgumentException("Invalid systemName");for(String c:new String[]{primaryColor,secondaryColor,backgroundColor,textColor})if(c==null||!HEX.matcher(c).matches())throw new IllegalArgumentException("Invalid color: "+c);}}
